INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('5to', 'Ciencias de la Naturaleza', 'BC1', 'IL-1', 'Interpreta de manera precisa el lenguaje científico y tecnológico considerando las ideas básicas y procesos científicos de la química, así como sus contextos y su alcance, asumiendo una posición crítica ante información o proceso pseudocientífico, partiendo de problemática de ejes temáticos transversales.'),
('5to', 'Ciencias de la Naturaleza', 'BC1', 'IL-2', 'Produce y comunica efectivamente informes de laboratorio, ensayo, resúmenes, proyectos, resolución de problema, presentación oral, carteles e información científica relacionada con los fundamentos de la química.'),
('5to', 'Ciencias de la Naturaleza', 'BC1', 'IL-3', 'Utiliza símbolos, términos, modelos, gráficas, ecuaciones y definiciones de la química, leyes y convenciones químicas y tecnológicas de forma adecuadas.'),

-- BC2
('5to', 'Ciencias de la Naturaleza', 'BC2', 'IL-4', 'Utiliza estrategias efectivas en la búsqueda de evidencias para dar respuesta a problemas o situaciones relacionadas con la química.'),
('5to', 'Ciencias de la Naturaleza', 'BC2', 'IL-5', 'Aplica de forma adecuada los conceptos, principios, ideas, modelos y leyes presentes en problemas y fenómenos químicos, diseñando y aplicando estrategias en la búsqueda de soluciones, tanto en términos cualitativos como cuantitativos.'),
('5to', 'Ciencias de la Naturaleza', 'BC2', 'IL-6', 'Formula, analiza y evalúa pertinentemente las evidencias que dan respuestas a problemas y fenómenos asociados con explicación química, comprendiendo el alcance de los conceptos, modelos, principios, teoría y leyes.'),
('5to', 'Ciencias de la Naturaleza', 'BC2', 'IL-7', 'Utiliza y evalúa efectivamente diversas estrategias, procedimientos, herramientas técnicas, para solucionar, diseñar y ejecutar experimentos con base en la química.'),
('5to', 'Ciencias de la Naturaleza', 'BC2', 'IL-8', 'Formula, ejecuta y evalúa efectivamente experimentos, estructuras, herramientas, sistemas y mecanismo para dar respuesta al problema o fenómeno natural asociada con la química.'),
('5to', 'Ciencias de la Naturaleza', 'BC2', 'IL-9', 'Construye, utiliza y evalúa apropiadamente objetos, herramientas y estructuras proponiendo mecanismo y modelos que le permitan dar respuestas a situaciones y problemas vinculado a la química.'),

